rRaw = 0.0
if bar_index == 0 {
    rRaw := 0.0
} else {
    rRaw := (close - close[1]) / (close[1] + 0.000000001)
}

var retHist = [0.0]
var closeHist = [0.0]
var firstBar = 1.0

if firstBar == 1.0 {
    array.push(retHist, rRaw)
    array.push(closeHist, close)
    firstBar := 0.0
} else {
    array.push(retHist, rRaw)
    array.push(closeHist, close)
}

nBars = array.size(retHist)
curIdx = nBars - 1

curNorm = 0.0
sumSqCur = 0.0
ii = 0
while ii < featBars {
    pos = curIdx - ii
    rv = 0.0
    if pos >= 0 {
        rv := retHist[pos]
    }
    sumSqCur := sumSqCur + rv * rv
    ii := ii + 1
}
curNorm := sqrt(sumSqCur + 0.000000001)

bullCount = 0
bearCount = 0
margin = 0.0
disRaw = 1.0
disNorm = 1.0
meanD = 0.0
sdD = 0.0
readyBar = bar_index >= minHist and nBars >= minHist + featBars

if readyBar {
    bestD = [999999.0, 999999.0, 999999.0, 999999.0, 999999.0, 999999.0, 999999.0]
    bestL = [0, 0, 0, 0, 0, 0, 0]
    searchStart = curIdx - histLook
    if searchStart < featBars {
        searchStart := featBars
    }
    if searchStart < 1 {
        searchStart := 1
    }
    jj = searchStart
    while jj < curIdx {
        normJ = 0.0
        ss = 0.0
        qq = 0
        while qq < featBars {
            ppos = jj - qq
            vv = 0.0
            if ppos >= 0 {
                vv := retHist[ppos]
            }
            ss := ss + vv * vv
            qq := qq + 1
        }
        normJ := sqrt(ss + 0.000000001)
        distSq = 0.0
        qq2 = 0
        while qq2 < featBars {
            curV = retHist[curIdx - qq2] / curNorm
            pastV = retHist[jj - qq2] / normJ
            df = curV - pastV
            distSq := distSq + df * df
            qq2 := qq2 + 1
        }
        dist = sqrt(distSq)
        lbl = 0 - 1
        nxtC = closeHist[jj + 1]
        curC = closeHist[jj]
        if nxtC > curC {
            lbl := 1
        }
        insertAt = 0 - 1
        mm = 0
        while mm < kIn {
            if dist < bestD[mm] {
                insertAt := mm
                mm := kIn
            }
            mm := mm + 1
        }
        if insertAt >= 0 {
            mm2 = kIn - 1
            while mm2 > insertAt {
                array.set(bestD, mm2, bestD[mm2 - 1])
                array.set(bestL, mm2, bestL[mm2 - 1])
                mm2 := mm2 - 1
            }
            array.set(bestD, insertAt, dist)
            array.set(bestL, insertAt, lbl)
        }
        jj := jj + 1
    }
    bc = 0
    sc = 0
    mm3 = 0
    while mm3 < kIn {
        if bestD[mm3] < 999998.0 {
            if bestL[mm3] == 1 {
                bc := bc + 1
            } else {
                sc := sc + 1
            }
        }
        mm3 := mm3 + 1
    }
    bullCount := bc
    bearCount := sc
    tot = bc + sc
    mg = 0.0
    if tot > 0 {
        mg := (bc - sc) / tot
    }
    margin := mg
    sMean = 0.0
    sCnt = 0
    mm4 = 0
    while mm4 < kIn {
        if bestD[mm4] < 999998.0 {
            sMean := sMean + bestD[mm4]
            sCnt := sCnt + 1
        }
        mm4 := mm4 + 1
    }
    avgD = 0.0
    if sCnt > 0 {
        avgD := sMean / sCnt
    }
    meanD := avgD
    varD = 0.0
    mm5 = 0
    while mm5 < kIn {
        if bestD[mm5] < 999998.0 {
            dd = bestD[mm5] - avgD
            varD := varD + dd * dd
        }
        mm5 := mm5 + 1
    }
    sdv = 0.0
    if sCnt > 0 {
        sdv := sqrt(varD / sCnt)
    }
    sdD := sdv
    dr = sdv / (avgD + 0.000000001)
    disRaw := dr
    dn = dr / 2.0
    if dn > 1.0 {
        dn := 1.0
    }
    if dn < 0.0 {
        dn := 0.0
    }
    disNorm := dn
}

